// Package docs reads the documents a company already has into deck source.
//
// Ptium's premise is that the material for a deck already exists: last
// quarter's report is a .docx, the numbers are an .xlsx, the notes are
// markdown. Asking someone to retype all of it into a brief is asking them to
// do the work twice, and what they retype loses the one thing that matters
// most — where each figure came from.
//
// So a document is read into the same deck source everything else compiles
// from, and every slide it produces cites the file and the place in it. What
// cannot be read is said out loud rather than guessed at.
//
// Everything here is the standard library. A deployment with no network and no
// system packages reads these files the same way one with everything does.
package docs

import (
	"fmt"
	"path"
	"strings"
)

// Document is a file, read as deck source.
type Document struct {
	// Title is what the file called itself, when it said.
	Title string
	// Source is deck source: the same language the editor edits.
	Source string
	// Warnings are for the person who uploaded the file, in their language.
	Warnings []string
}

// ErrUnsupported says the file is not one this package reads.
type ErrUnsupported struct{ Extension string }

func (e ErrUnsupported) Error() string {
	return fmt.Sprintf("no reader for %q", e.Extension)
}

// Extensions are what Read accepts, for the upload dialog to name.
var Extensions = []string{".csv", ".tsv", ".xlsx", ".docx", ".pdf", ".md", ".markdown", ".txt"}

// Reads reports whether a file name is one this package can read.
func Reads(filename string) bool {
	extension := strings.ToLower(path.Ext(strings.TrimSpace(filename)))
	for _, candidate := range Extensions {
		if extension == candidate {
			return true
		}
	}
	return false
}

// Read turns a file into deck source.
func Read(filename string, data []byte) (Document, error) {
	name := strings.TrimSpace(path.Base(filename))
	extension := strings.ToLower(path.Ext(name))
	// A spreadsheet or a note carries no declaration of what it is written in,
	// so the bytes are read as text before anything reads them as a document.
	// The formats below this are packages that say for themselves.
	switch extension {
	case ".csv", ".tsv", ".md", ".markdown", ".txt":
		text, ok := asText(data)
		if !ok {
			return Document{}, fmt.Errorf(
				"이 파일의 글자를 읽지 못했습니다. UTF-8 이나 CP949 로 저장한 뒤 다시 올려 주세요")
		}
		data = []byte(text)
	}
	switch extension {
	case ".csv":
		return readSeparated(name, data, ',')
	case ".tsv":
		return readSeparated(name, data, '\t')
	case ".xlsx":
		return readWorkbook(name, data)
	case ".docx":
		return readWordDocument(name, data)
	case ".pdf":
		return readPDF(name, data)
	case ".md", ".markdown", ".txt":
		return readMarkdown(name, data)
	}
	return Document{}, ErrUnsupported{Extension: path.Ext(name)}
}

// titleOf is what to call a deck made from a file: the file's own name,
// without the extension.
func titleOf(filename string) string {
	name := strings.TrimSpace(path.Base(filename))
	if extension := path.Ext(name); extension != "" {
		name = strings.TrimSuffix(name, extension)
	}
	if name == "" {
		return "가져온 문서"
	}
	return name
}

// A slide built from a file says which file, and where in it. The locator is
// what someone would type to find it again: a sheet and a range, a heading.
func citation(filename, locator string) string {
	if strings.TrimSpace(locator) == "" {
		return fmt.Sprintf("!source %s\n", escapeField(filename))
	}
	return fmt.Sprintf("!source %s | %s\n", escapeField(filename), escapeField(locator))
}

// escapeField protects a value from being read as another field.
func escapeField(value string) string {
	return strings.TrimSpace(strings.ReplaceAll(strings.ReplaceAll(value, "|", "/"), "\n", " "))
}

// escapeNote fits a note onto the one line a "!notes" directive occupies.
//
// A note is not a field: nothing after "!notes" is a separator, so the bar in
// "단가 | 수수료 | 거래세" is the document's own punctuation and turning it into a
// slash rewrites what somebody wrote. Sixteen lines of the files this was
// measured against are written exactly that way.
func escapeNote(value string) string {
	return strings.Join(strings.Fields(value), " ")
}

// escapeLine protects text from being read as a directive.
func escapeLine(value string) string {
	trimmed := strings.TrimSpace(strings.ReplaceAll(value, "\n", " "))
	if trimmed == "" {
		return trimmed
	}
	switch trimmed[0] {
	case '#', '\\', '-', '*', '>', '!', '@':
		return "\\" + trimmed
	}
	return trimmed
}

// maximum sizes. A document is material for a deck, not the deck: a hundred
// rows of a spreadsheet on one slide is a screenshot of a spreadsheet.
const (
	maximumSlides  = 30
	maximumRows    = 8
	maximumColumns = 5
	// A sheet that runs longer than this is a spreadsheet, not a deck: what is
	// past it is said rather than drawn.
	maximumTableSlides = 4
	maximumPoints      = 5
)

// readWorkbook reads a spreadsheet into slides, one per sheet.
func readWorkbook(filename string, data []byte) (Document, error) {
	archive, err := zip.NewReader(bytes.NewReader(data), int64(len(data)))
	if err != nil {
		return Document{}, fmt.Errorf("이 파일은 엑셀 통합 문서가 아닙니다")
	}
	parts := map[string][]byte{}
	for _, file := range archive.File {
		opened, err := file.Open()
		if err != nil {
			continue
		}
		content, err := io.ReadAll(io.LimitReader(opened, 32<<20))
		opened.Close()
		if err == nil {
			parts[file.Name] = content
		}
	}
	var index workbookIndex
	if err := xml.Unmarshal(parts["xl/workbook.xml"], &index); err != nil || len(index.Sheets.Sheet) == 0 {
		return Document{}, fmt.Errorf("이 통합 문서에서 시트를 찾지 못했습니다")
	}
	var relationships workbookRelationships
	_ = xml.Unmarshal(parts["xl/_rels/workbook.xml.rels"], &relationships)
	target := map[string]string{}
	for _, relationship := range relationships.Relationship {
		target[relationship.ID] = strings.TrimPrefix(relationship.Target, "/")
	}
	var strings0 sharedStrings
	_ = xml.Unmarshal(parts["xl/sharedStrings.xml"], &strings0)
	// What each style means, so a date is a day and a per cent is a per cent —
	// and which day the workbook counts its days from, so the day is the one on
	// the sheet.
	formats := readCellFormats(parts["xl/styles.xml"], counts1904(index.Properties.Date1904))
	shared := make([]string, 0, len(strings0.Items))
	for _, item := range strings0.Items {
		if item.Text != "" {
			shared = append(shared, item.Text)
			continue
		}
		shared = append(shared, strings.Join(item.Runs, ""))
	}

	document := Document{Title: titleOf(filename)}
	var builder strings.Builder
	fmt.Fprintf(&builder, "# %s\n@cover\n> %s\n\n", escapeLine(document.Title), escapeLine(filename))
	written := 0
	var warnings []string
	var hidden []string
	var left []string
	for _, sheet := range index.Sheets.Sheet {
		// A workbook says which of its sheets it hides, and a hidden sheet is
		// one nobody meant anyone to see: the code table a formula looks up in,
		// the settings a macro reads, last quarter's working copy. Taken as if
		// it were visible, it became a slide in the middle of the deck.
		if sheetHidden(sheet.State) {
			hidden = append(hidden, sheet.Name)
			continue
		}
		name := target[sheet.ID]
		if name == "" {
			continue
		}
		content, ok := parts[sheetPart(name)]
		if !ok {
			continue
		}
		var parsed worksheet
		if err := xml.Unmarshal(content, &parsed); err != nil {
			continue
		}
		rows, at, hiddenRows, hiddenColumns := onScreen(parsed, gridOf(parsed, shared, formats))
		// A deck holds so many slides, and a workbook of forty sheets runs out
		// of deck before it runs out of sheets. What was left out is what the
		// person who uploaded it has to know, and naming it is the only way
		// they can: "시트가 많아 앞 30개만 가져왔습니다" named neither, and the
		// number in it was how many slides a deck holds — so a workbook whose
		// sheets each fill three slides said it had taken the first thirty of
		// its eleven. A sheet with nothing on it was never going to be a
		// slide, so it is not something that was left out.
		if written >= maximumSlides {
			if len(trimGrid(rows)) >= 2 {
				left = append(left, sheet.Name)
			}
			continue
		}
		count, sheetWarnings := writeSheet(&builder, filename, sheet.Name, rows, at)
		written += count
		warnings = append(warnings, sheetWarnings...)
		// What was hidden is worth a line only under a slide it was hidden
		// from; a sheet that made no slide left nothing out of one.
		if count > 0 {
			if concealed := concealedNamed(hiddenRows, hiddenColumns); concealed != "" {
				warnings = append(warnings, fmt.Sprintf("%s의 숨긴 %s 가져오지 않았습니다",
					sheetLabel(filename, sheet.Name), concealed))
			}
		}
	}
	if written == 0 {
		// Why there is nothing to show matters when the file plainly has
		// figures in it: "읽을 표가 없습니다" sends someone back to a workbook
		// they can see the numbers in, to look for what is wrong with it.
		if len(hidden) > 0 {
			return Document{}, fmt.Errorf("이 통합 문서의 시트(%s)는 모두 숨겨져 있습니다",
				sheetsNamed(hidden))
		}
		return Document{}, fmt.Errorf("이 통합 문서에는 읽을 표가 없습니다")
	}
	if len(left) > 0 {
		warnings = append(warnings, fmt.Sprintf(
			"슬라이드가 많아 시트(%s)는 가져오지 않았습니다. 나눠서 올리면 전부 가져옵니다",
			sheetsNamed(left)))
	}
	if len(hidden) > 0 {
		warnings = append(warnings, fmt.Sprintf("숨겨진 시트(%s)는 가져오지 않았습니다",
			sheetsNamed(hidden)))
	}
	document.Source = builder.String()
	document.Warnings = warnings
	return document, nil
}

// sheetHidden reports whether a workbook hides a sheet. "veryHidden" is the
// one only a macro can put back, which is further from being meant for a deck
// rather than nearer; anything else, including the state a sheet writes by
package docs

import (
	"fmt"
	"strings"
	"testing"
)

// A report's table is longer than a slide holds, and cutting it at the eighth
// row is how a twelve-row table arrived as eight rows with the rest on no slide
// and nobody told. It continues on the next slide instead, header and all.
func TestALongTableContinuesOnTheNextSlide(t *testing.T) {
	rows := [][]string{{"구분", "내용"}}
	for index := 1; index <= 12; index++ {
		rows = append(rows, []string{fmt.Sprintf("항목%d", index), fmt.Sprintf("값%d", index)})
	}
	writer := newDeckWriter("보고서.docx", "보고서")
	writer.slide("추진 실적")
	writer.table(rows)
	document, err := writer.document()
	if err != nil {
		t.Fatalf("document: %v", err)
	}
	for index := 1; index <= 12; index++ {
		if !strings.Contains(document.Source, fmt.Sprintf("항목%d", index)) {
			t.Errorf("row %d is on no slide:\n%s", index, document.Source)
		}
	}
	headings := 0
	for _, line := range strings.Split(document.Source, "\n") {
		if line == "# 추진 실적" {
			headings++
		}
	}
	if headings != 2 || !strings.Contains(document.Source, "# 추진 실적 (계속)") {
		t.Errorf("the table did not continue on a slide of its own:\n%s", document.Source)
	}
	// Every piece carries the header, or a continuation reads as a list of
	// values with nothing to say what they are.
	if strings.Count(document.Source, "- 구분 | 내용") != 2 {
		t.Errorf("the header is not repeated on the continuation:\n%s", document.Source)
	}
}

// A table wider than a slide holds keeps the columns that fit, and says which
// ones it left.
func TestAWideTableSaysWhatItLeft(t *testing.T) {
	writer := newDeckWriter("보고서.docx", "보고서")
	writer.slide("현황")
	writer.table([][]string{
		{"번호", "구분", "내용", "담당", "기한", "비고"},
		{"1", "운영", "ITSM 개선", "김", "2월", "진행"},
	})
	document, err := writer.document()
	if err != nil {
		t.Fatalf("document: %v", err)
	}
	said := strings.Join(document.Warnings, " | ")
	if !strings.Contains(said, "열") {
		t.Errorf("a six-column table was cut to five and said %q", said)
	}
	if strings.Contains(document.Source, "비고") {
		t.Errorf("the sixth column was written after all:\n%s", document.Source)
	}
}

// A table that fits says nothing and stays on one slide.
func TestAnOrdinaryTableIsLeftAlone(t *testing.T) {
	writer := newDeckWriter("보고서.docx", "보고서")
	writer.slide("현황")
	writer.table([][]string{{"항목", "2026"}, {"인건비", "4.2"}, {"운영비", "1.1"}})
	document, err := writer.document()
	if err != nil {
		t.Fatalf("document: %v", err)
	}
	if strings.Contains(document.Source, "(계속)") {
		t.Errorf("a three-row table was split:\n%s", document.Source)
	}
	if len(document.Warnings) != 0 {
		t.Errorf("an ordinary table was reported: %v", document.Warnings)
	}
}

// A spreadsheet is read the same way: twelve rows are a table, not the first
// eight rows of one. Past a few slides it is a spreadsheet rather than a deck,
// and what is left is said instead of drawn.
func TestASheetLongerThanASlideContinues(t *testing.T) {
	rows := func(count int) [][]string {
		grid := [][]string{{"구분", "내용"}}
		for index := 1; index <= count; index++ {
			grid = append(grid, []string{fmt.Sprintf("항목%d", index), fmt.Sprintf("값%d", index)})
		}
		return grid
	}
	var builder strings.Builder
	written, warnings := writeSheet(&builder, "실적.csv", "", rows(12), placement{})
	if written != 2 {
		t.Errorf("a twelve-row sheet wrote %d slides", written)
	}
	for index := 1; index <= 12; index++ {
		if !strings.Contains(builder.String(), fmt.Sprintf("항목%d", index)) {
			t.Errorf("row %d is on no slide:\n%s", index, builder.String())
		}
	}
	if len(warnings) != 0 {
		t.Errorf("a table that was carried whole was reported: %v", warnings)
	}

	// A sheet nobody would sit through says what it left.
	builder.Reset()
	written, warnings = writeSheet(&builder, "실적.csv", "", rows(40), placement{})
	if written != maximumTableSlides {
		t.Errorf("a forty-row sheet wrote %d slides", written)
	}
	if !strings.Contains(strings.Join(warnings, " "), "32줄") {
		t.Errorf("a forty-row sheet said %v", warnings)
	}

	// And a short one is one slide, as it was.
	builder.Reset()
	if written, warnings = writeSheet(&builder, "실적.csv", "", rows(3), placement{}); written != 1 || len(warnings) != 0 {
		t.Errorf("a three-row sheet wrote %d slides and said %v", written, warnings)
	}
}
